(567946, 58533, 12902, '<td valign="top">This is the photo that grabbed my eye from the thumbnails. Excellent. I am sure that will be a ribbon. You might have a few complains about the negative space though. 10 from me.</td>', 'This is the photo that grabbed my eye from the thumbnails. Excellent. I am sure that will be a ribbon. You might have a few complains about the negative space though. 10 from me.', '2004-02-04 05:40:35.000000', NULL, 1),
(567948, 58212, 12902, '<td valign="top">Excellent. I love this picture. It should make it to top 10 at least if not a ribbon. 10</td>', 'Excellent. I love this picture. It should make it to top 10 at least if not a ribbon. 10', '2004-02-04 05:42:04.000000', NULL, 1),
(567951, 57798, 5364, '<td valign="top">The technicallities of this are good (composition, focus etc)  but I think I would like it more if it had slightly more contrast, although the way it is does illustrate the low contrast lighting of a British winter!</td>', 'The technicallities of this are good (composition, focus etc)  but I think I would like it more if it had slightly more contrast, although the way it is does illustrate the low contrast lighting of a British winter!', '2004-02-04 05:45:04.000000', NULL, 1),
(567953, 57933, 12902, '<td valign="top">I sure hope this is the blue ribbon. It deserves it. I envy your talent and your creativity. 10 and congratulations.</td>', 'I sure hope this is the blue ribbon. It deserves it. I envy your talent and your creativity. 10 and congratulations.', '2004-02-04 05:46:38.000000', NULL, 1),
(567954, 58422, 5364, '<td valign="top">Nicely done, but the highlight on the blade is a bit distracting</td>', 'Nicely done, but the highlight on the blade is a bit distracting', '2004-02-04 05:48:32.000000', NULL, 1),
(567956, 57726, 12902, '<td valign="top">Very pretty. I wish you had the tape more in focus or gave the photo another title. But I still like it a lot. 10</td>', 'Very pretty. I wish you had the tape more in focus or gave the photo another title. But I still like it a lot. 10', '2004-02-04 05:49:45.000000', NULL, 1),
(567958, 58398, 12902, '<td valign="top">One of the ribbons I am sure. Wonderful photo and very creative setup. 10</td>', 'One of the ribbons I am sure. Wonderful photo and very creative setup. 10', '2004-02-04 05:51:00.000000', NULL, 1),
(567960, 57715, 12902, '<td valign="top">The photo is wonderful. Too bad I don''t understand the title. 10 for the photo anyway.</td>', 'The photo is wonderful. Too bad I don''t understand the title. 10 for the photo anyway.', '2004-02-04 05:52:44.000000', NULL, 1),
(567961, 57715, 14499, '<td valign="top">I love it, I think people may score it down as you don''t oftten find Apples in the garage.. unless they are rotting in a bin maybe. time will tell! 10 from me!</td>', 'I love it, I think people may score it down as you don''t oftten find Apples in the garage.. unless they are rotting in a bin maybe. time will tell! 10 from me!', '2004-02-04 05:52:48.000000', NULL, 1),
