(568622, 57798, 15197, '<td valign="top">I like the angle that you took the photo from.  Things look so much better when they are off center.</td>', 'I like the angle that you took the photo from.  Things look so much better when they are off center.', '2004-02-04 13:49:01.000000', NULL, 1),
(568623, 58004, 15197, '<td valign="top">I like the color of the rope.  The background is a bit too busy, but still a good choice.</td>', 'I like the color of the rope.  The background is a bit too busy, but still a good choice.', '2004-02-04 13:49:34.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(568627, 58522, 15197, '<td valign="top">I like the black background, but the composition is lacking somewhat.  Getting the upper right tool piece in clear focus may have helped.</td>', 'I like the black background, but the composition is lacking somewhat.  Getting the upper right tool piece in clear focus may have helped.', '2004-02-04 13:51:26.000000', NULL, 1),
(568628, 58023, 12654, '<td valign="top">You could have done this in a much better way if you had only spent some time with the lighting and a few more minor adjustments. You could have atleast focused on the wrenches.<br/></td>', 'You could have done this in a much better way if you had only spent some time with the lighting and a few more minor adjustments. You could have atleast focused on the wrenches.', '2004-02-04 13:51:36.000000', NULL, 1),
(568629, 57797, 15197, '<td valign="top">I love yellows in pictures.  Nice capture of that.  The wheel seems off placement somehow.  Maybe placing it in a different place would have helped?  Good job.</td>', 'I love yellows in pictures.  Nice capture of that.  The wheel seems off placement somehow.  Maybe placing it in a different place would have helped?  Good job.', '2004-02-04 13:52:23.000000', NULL, 1),
(568630, 57864, 15197, '<td valign="top">I can relate to this scene!  Did you use "sharpen" in a program?  It looks a bit "over sharpened" if so.  I like the red color of the car.  Funny title.</td>', 'I can relate to this scene!  Did you use "sharpen" in a program?  It looks a bit "over sharpened" if so.  I like the red color of the car.  Funny title.', '2004-02-04 13:53:33.000000', NULL, 1),
(568631, 58520, 12654, '<td valign="top">nicely done.</td>', 'nicely done.', '2004-02-04 13:53:58.000000', NULL, 1),
(568633, 58492, 15197, '<td valign="top">I can tell you tried for an interesting composition.  Good job.  What''s missing?  Maybe a bit clearer focus would have helped.  I like the black background.</td>', 'I can tell you tried for an interesting composition.  Good job.  What''s missing?  Maybe a bit clearer focus would have helped.  I like the black background.', '2004-02-04 13:55:07.000000', NULL, 1),
(568635, 58415, 15197, '<td valign="top">Interesting assortment, but the composition isn''t interesting to me.  I like the gray background.  I would have brought the red tool more into play.  Red and gray look good  together.</td>', 'Interesting assortment, but the composition isn''t interesting to me.  I like the gray background.  I would have brought the red tool more into play.  Red and gray look good  together.', '2004-02-04 13:56:03.000000', NULL, 1),
(568636, 58519, 12654, '<td valign="top">Very cool, but err...... shouldn''t you be holding the hammer the other way - unless of course yuo were rying to scratch your back.<br/>But overall - i like the pic- and it looks good in monotone.</td>', 'Very cool, but err...... shouldn''t you be holding the hammer the other way - unless of course yuo were rying to scratch your back.But overall - i like the pic- and it looks good in monotone.', '2004-02-04 13:56:11.000000', NULL, 1),
(568637, 57874, 15197, '<td valign="top">Did you compose this?  The best feature is the window with the cobwebs.  That is a very attractive capturing of that.  The green bottle almost distracts...but I still like it.  Good job.</td>', 'Did you compose this?  The best feature is the window with the cobwebs.  That is a very attractive capturing of that.  The green bottle almost distracts...but I still like it.  Good job.', '2004-02-04 13:57:20.000000', NULL, 1),
(568640, 57609, 15197, '<td valign="top">The velvet draping is very well done.  It would have been fun to see some paint "ooze" out on it!</td>', 'The velvet draping is very well done.  It would have been fun to see some paint "ooze" out on it!', '2004-02-04 14:00:12.000000', NULL, 1),
