(569251, 57871, 15032, '<td valign="top">Great!  Nice parking job.  Would have liked to have seen the picture rotated clockwise about .5 degrees so the lines on the house are parallel to the border</td>', 'Great!  Nice parking job.  Would have liked to have seen the picture rotated clockwise about .5 degrees so the lines on the house are parallel to the border', '2004-02-04 23:00:38.000000', NULL, 1),
(569253, 57479, 327, '<td valign="top">Cute little fella. I think you should use him as a model if he''ll hold still. Darling boy. This shot is over exposed and a bit out of focus.</td>', 'Cute little fella. I think you should use him as a model if he''ll hold still. Darling boy. This shot is over exposed and a bit out of focus.', '2004-02-04 23:01:08.000000', NULL, 1),
(569255, 58478, 327, '<td valign="top">Sometimes ideas work and sometimes they don''t. This is a good idea, but looks as if the compression has distorted your pixels.</td>', 'Sometimes ideas work and sometimes they don''t. This is a good idea, but looks as if the compression has distorted your pixels.', '2004-02-04 23:01:58.000000', NULL, 1),
(569256, 57753, 327, '<td valign="top">Wow, fantastic colors. Not very garage like, but yes, great colors and interesting shot. Needs a bit more focus but cool colors.</td>', 'Wow, fantastic colors. Not very garage like, but yes, great colors and interesting shot. Needs a bit more focus but cool colors.', '2004-02-04 23:02:55.000000', NULL, 1),
(569258, 58292, 327, '<td valign="top">Fisher-Price the best. Had them for my daughter and grandsons. Creative entry.</td>', 'Fisher-Price the best. Had them for my daughter and grandsons. Creative entry.', '2004-02-04 23:03:46.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(569261, 58326, 327, '<td valign="top">Most unusual peice of wood!!!....looks like a neat hobby.</td>', 'Most unusual peice of wood!!!....looks like a neat hobby.', '2004-02-04 23:04:25.000000', NULL, 1),
(569262, 58482, 327, '<td valign="top">Maybe leaving out the over exposed white fender would of helped your shot some. I do think this is a good idea, but we need to see something more then what is shown here. The focus seems off but I think it''s just that the focus is on the tire more then anywhere else.</td>', 'Maybe leaving out the over exposed white fender would of helped your shot some. I do think this is a good idea, but we need to see something more then what is shown here. The focus seems off but I think it''s just that the focus is on the tire more then anywhere else.', '2004-02-04 23:05:37.000000', NULL, 1),
(569263, 57479, 772, '<td valign="top">I can''t see how this photo relates to the challenge topic.</td>', 'I can''t see how this photo relates to the challenge topic.', '2004-02-04 23:05:52.000000', NULL, 1),
(569265, 58265, 327, '<td valign="top">This shot is not without interest....IMHO, I like sparks and I think this is good. I guess the dead space on the right could of been eliminated.</td>', 'This shot is not without interest....IMHO, I like sparks and I think this is good. I guess the dead space on the right could of been eliminated.', '2004-02-04 23:08:27.000000', NULL, 1),
(569279, 58102, 11394, '<td valign="top">Congrats on your placement in the zodiac challenge.  It makes a nice addition to your garage, the whole foe window thing is cool. Good luck with this challenge and hope you do well.</td>', 'Congrats on your placement in the zodiac challenge.  It makes a nice addition to your garage, the whole foe window thing is cool. Good luck with this challenge and hope you do well.', '2004-02-04 23:22:38.000000', NULL, 1),
