(569284, 57609, 15305, '<td valign="top">Nice composition and background.</td>', 'Nice composition and background.', '2004-02-04 23:26:10.000000', NULL, 1),
(569287, 58193, 15305, '<td valign="top">Great mood created by the use of sepia and the elements of the composition. I like it a lot!</td>', 'Great mood created by the use of sepia and the elements of the composition. I like it a lot!', '2004-02-04 23:27:25.000000', NULL, 1),
(569291, 58034, 15305, '<td valign="top">Nice use of DOF. I like the composition, the sharpness and the vivid colors.</td>', 'Nice use of DOF. I like the composition, the sharpness and the vivid colors.', '2004-02-04 23:28:33.000000', NULL, 1),
(569298, 57726, 15305, '<td valign="top">Interesting composition and technique. Great DOF.</td>', 'Interesting composition and technique. Great DOF.', '2004-02-04 23:31:39.000000', NULL, 1),
(569301, 57608, 15305, '<td valign="top">Great macro shot!! Interesting texture and composition.</td>', 'Great macro shot!! Interesting texture and composition.', '2004-02-04 23:33:14.000000', NULL, 1),
(569304, 58392, 15305, '<td valign="top">Interesting composition. I like the lighting and use of B&amp;W</td>', 'Interesting composition. I like the lighting and use of B&W', '2004-02-04 23:34:25.000000', NULL, 1),
(569309, 58038, 15305, '<td valign="top">Nice idea, well executed.</td>', 'Nice idea, well executed.', '2004-02-04 23:39:12.000000', NULL, 1),
(569312, 58239, 15305, '<td valign="top">Nice composition, I like the reflections on the motorcycle.</td>', 'Nice composition, I like the reflections on the motorcycle.', '2004-02-04 23:39:52.000000', NULL, 1),
(569314, 58465, 15305, '<td valign="top">Nice macro shot.</td>', 'Nice macro shot.', '2004-02-04 23:40:39.000000', NULL, 1),
(569323, 58532, 14606, '<td valign="top">Wow, this rocks!</td>', 'Wow, this rocks!', '2004-02-04 23:44:33.000000', NULL, 1),
