(569356, 58472, 518, '<td valign="top">I love these nostalgic colors</td>', 'I love these nostalgic colors', '2004-02-05 00:24:18.000000', NULL, 1),
(569358, 57397, 518, '<td valign="top">Very nice exposure.  Snow adds some great difficulty, and your perspective from thee dark garage is awesome.</td>', 'Very nice exposure.  Snow adds some great difficulty, and your perspective from thee dark garage is awesome.', '2004-02-05 00:27:11.000000', NULL, 1),
