(569363, 57911, 259, '<td valign="top">very impressive.  great lighting and mood.</td>', 'very impressive.  great lighting and mood.', '2004-02-05 00:31:51.000000', NULL, 1),
(569364, 58238, 15477, '<td valign="top">Very creative shot! A little more symmetry in terms of size when placing the bolts would''ve helped I think, but overall a very good pic. Good luck.</td>', 'Very creative shot! A little more symmetry in terms of size when placing the bolts would''ve helped I think, but overall a very good pic. Good luck.', '2004-02-05 00:32:34.000000', NULL, 1),
(569365, 57871, 518, '<td valign="top">hilarious -i love it</td>', 'hilarious -i love it', '2004-02-05 00:32:37.000000', NULL, 1),
(569366, 58331, 15477, '<td valign="top">Very interesting to look at - I think I would have scored it higher if it wasn''t so bight. Good luck.</td>', 'Very interesting to look at - I think I would have scored it higher if it wasn''t so bight. Good luck.', '2004-02-05 00:36:04.000000', NULL, 1),
