(569408, 57708, 15197, '<td valign="top">Very nice.  I just love the detail on the spout of the oil can.</td>', 'Very nice.  I just love the detail on the spout of the oil can.', '2004-02-05 01:13:54.000000', NULL, 1),
(569412, 57471, 15197, '<td valign="top">I like the background color.</td>', 'I like the background color.', '2004-02-05 01:15:22.000000', NULL, 1),
