(569996, 57708, 10339, '<td valign="top">Nice colors and shadows.</td>', 'Nice colors and shadows.', '2004-02-05 14:44:50.000000', NULL, 1),
(569997, 58359, 9462, '<td valign="top">LOL</td>', 'LOL', '2004-02-05 14:44:54.000000', NULL, 1),
(569999, 58288, 9462, '<td valign="top">too sterile... and uninteresting</td>', 'too sterile... and uninteresting', '2004-02-05 14:46:35.000000', NULL, 1),
(570002, 58493, 9462, '<td valign="top">Interesting angles.</td>', 'Interesting angles.', '2004-02-05 14:48:53.000000', NULL, 1),
(570007, 58482, 9462, '<td valign="top">Sorry, but this really sucks... in every way possible.</td>', 'Sorry, but this really sucks... in every way possible.', '2004-02-05 14:53:58.000000', NULL, 1),
