(570691, 57370, 16034, '<td valign="top">Nice Colors -  and Shine</td>', 'Nice Colors -  and Shine', '2004-02-06 05:58:16.000000', NULL, 1),
(570693, 58113, 10370, '<td valign="top">I like the idea and I see what you were trying to do but the composition is a bit too uncomfortable for my liking and the DoF too shallow. The foreground nuts are too distracting. Might have benefitted from a wider angle to increase the perspective.<br/>Love the colours with the green/blue bits.</td>', 'I like the idea and I see what you were trying to do but the composition is a bit too uncomfortable for my liking and the DoF too shallow. The foreground nuts are too distracting. Might have benefitted from a wider angle to increase the perspective.Love the colours with the green/blue bits.', '2004-02-06 06:08:09.000000', NULL, 1),
(570694, 58464, 10370, '<td valign="top">I originally only saw the top three quarters of this and loved it but when I scrolled down the space below ruined it. A tighter crop from below would dramatically improve this great concept. The space on the right does work well.</td>', 'I originally only saw the top three quarters of this and loved it but when I scrolled down the space below ruined it. A tighter crop from below would dramatically improve this great concept. The space on the right does work well.', '2004-02-06 06:10:55.000000', NULL, 1),
(570695, 58392, 10370, '<td valign="top">Love the idea. It''s amaxing to be able to get so much character into the wrench in a still photo.</td>', 'Love the idea. It''s amaxing to be able to get so much character into the wrench in a still photo.', '2004-02-06 06:12:44.000000', NULL, 1),
(570697, 58493, 10370, '<td valign="top">I realise the DoF is deliberate but I think it would benefit from being a bit deeper. Otherwise I really like this one. If I was nit-picking I''d say that  the screw third from the right at the bottom is too distracting. But I''m not - so I won''t !</td>', 'I realise the DoF is deliberate but I think it would benefit from being a bit deeper. Otherwise I really like this one. If I was nit-picking I''d say that  the screw third from the right at the bottom is too distracting. But I''m not - so I won''t !', '2004-02-06 06:15:06.000000', NULL, 1),
(570698, 58453, 10370, '<td valign="top">Not original but brilliantly taken and crisp with a perfect DoF.</td>', 'Not original but brilliantly taken and crisp with a perfect DoF.', '2004-02-06 06:15:53.000000', NULL, 1),
(570699, 57726, 10370, '<td valign="top">Not very original and at least some of the tape needs to be in focus but I love the colours, crispness of the drops and the concept.</td>', 'Not very original and at least some of the tape needs to be in focus but I love the colours, crispness of the drops and the concept.', '2004-02-06 06:18:00.000000', NULL, 1),
(570700, 58429, 10370, '<td valign="top">I like this but it looks manipulated. What''s going on with the lighbulb and the figure?</td>', 'I like this but it looks manipulated. What''s going on with the lighbulb and the figure?', '2004-02-06 06:20:11.000000', NULL, 1),
