(570818, 57787, 15770, '<td valign="top">Nice, but I would have liked it better if the bolt was a little better focused.</td>', 'Nice, but I would have liked it better if the bolt was a little better focused.', '2004-02-06 10:10:55.000000', NULL, 1),
