(571720, 58422, 3306, '<td valign="top">Nicely set up and interesting. Definitely the feel of a garage workroom. The glare off the blade near the top is a little distracting.</td>', 'Nicely set up and interesting. Definitely the feel of a garage workroom. The glare off the blade near the top is a little distracting.', '2004-02-07 07:23:34.000000', NULL, 1),
(571721, 57785, 3306, '<td valign="top">Interesting picture. Very nicely exposed.</td>', 'Interesting picture. Very nicely exposed.', '2004-02-07 07:24:40.000000', NULL, 1),
(571722, 58000, 3306, '<td valign="top">Nicely composed point of view. You have probably already been told about rotating the picture slightly clockwise. People are kind of picky about that on DP Challenge. My picture has the same problem!</td>', 'Nicely composed point of view. You have probably already been told about rotating the picture slightly clockwise. People are kind of picky about that on DP Challenge. My picture has the same problem!', '2004-02-07 07:27:22.000000', NULL, 1),
(571723, 57715, 3306, '<td valign="top">Now that is different! Well composed and interesting.</td>', 'Now that is different! Well composed and interesting.', '2004-02-07 07:29:41.000000', NULL, 1),
(571724, 57992, 3306, '<td valign="top">Nicely composed and photographed. I Like the way you have set off your subject with the yellow backround and it looks like they are resting in some oil. There is a string or something on the top nut which is slightly distracting otherwise a technically well done picture.</td>', 'Nicely composed and photographed. I Like the way you have set off your subject with the yellow backround and it looks like they are resting in some oil. There is a string or something on the top nut which is slightly distracting otherwise a technically well done picture.', '2004-02-07 07:32:34.000000', NULL, 1),
(571725, 58472, 3306, '<td valign="top">This is a well done picture. I have seen many "bicylcle spoke" pictures which are OK but this one is very interesting. The lighting and texture really set off the rustic appearance. Almost looks like a painting. Good job.</td>', 'This is a well done picture. I have seen many "bicylcle spoke" pictures which are OK but this one is very interesting. The lighting and texture really set off the rustic appearance. Almost looks like a painting. Good job.', '2004-02-07 07:35:15.000000', NULL, 1),
(571727, 58415, 3306, '<td valign="top">Technically, your picture is OK. The pencil is somewhat overexposed and your point of focus is the middle of the picture where there is no object so that all of the tools are just slightly out of focus. Also I am not sure what of the idea you are trying to get across as I don''t see a relationship between all of the tools other than random tools placed on some black paper. I would have cropped out the lower portion of the picture to just below the shadow of the Pointed object on the left and that would have brought the viewer into the picture a little more.  Good Idea but needs work:)</td>', 'Technically, your picture is OK. The pencil is somewhat overexposed and your point of focus is the middle of the picture where there is no object so that all of the tools are just slightly out of focus. Also I am not sure what of the idea you are trying to get across as I don''t see a relationship between all of the tools other than random tools placed on some black paper. I would have cropped out the lower portion of the picture to just below the shadow of the Pointed object on the left and that would have brought the viewer into the picture a little more.  Good Idea but needs work:)', '2004-02-07 07:43:50.000000', NULL, 1),
(571737, 58493, 15305, '<td valign="top">Interesting composition. Nice DOF.</td>', 'Interesting composition. Nice DOF.', '2004-02-07 08:33:11.000000', NULL, 1),
(571738, 57627, 15305, '<td valign="top">Very interesting composition, excellent choice of color.</td>', 'Very interesting composition, excellent choice of color.', '2004-02-07 08:33:47.000000', NULL, 1),
(571739, 58215, 15305, '<td valign="top">Nice idea, interesting background texture.</td>', 'Nice idea, interesting background texture.', '2004-02-07 08:34:32.000000', NULL, 1),
(571740, 58338, 15305, '<td valign="top">Very interesting shot, nice use of lighting and the mood is superb.</td>', 'Very interesting shot, nice use of lighting and the mood is superb.', '2004-02-07 08:35:40.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(571741, 57479, 15305, '<td valign="top">Interesting shot, though it is really hard to compensate for a shadow cast from direct sunlight. I''d like to read your approach to the challenge when the voting period is over.</td>', 'Interesting shot, though it is really hard to compensate for a shadow cast from direct sunlight. I''d like to read your approach to the challenge when the voting period is over.', '2004-02-07 08:37:28.000000', NULL, 1),
(571742, 58520, 15305, '<td valign="top">Excellent shot, very nice composition, incredible use of light.</td>', 'Excellent shot, very nice composition, incredible use of light.', '2004-02-07 08:38:20.000000', NULL, 1),
(571744, 58513, 15305, '<td valign="top">Nice composition, it would be interesting to increase the contrast between the blue tools and the black background. Maybe another light source could help for this purpose.</td>', 'Nice composition, it would be interesting to increase the contrast between the blue tools and the black background. Maybe another light source could help for this purpose.', '2004-02-07 08:40:57.000000', NULL, 1),
(571746, 58188, 15305, '<td valign="top">Nice choice of subject, very vivid though the age. Really original.</td>', 'Nice choice of subject, very vivid though the age. Really original.', '2004-02-07 08:42:28.000000', NULL, 1),
(571747, 58326, 15305, '<td valign="top">This truly is art. Nice choice of B&amp;W.  Congratulations on your skills</td>', 'This truly is art. Nice choice of B&W.  Congratulations on your skills', '2004-02-07 08:43:14.000000', NULL, 1),
(571749, 57685, 15305, '<td valign="top">Interesting composition and choice of B&amp;W. Great light choice, creates an interesting mood.</td>', 'Interesting composition and choice of B&W. Great light choice, creates an interesting mood.', '2004-02-07 08:44:38.000000', NULL, 1),
(571750, 58102, 15305, '<td valign="top">Very interesting approach to the challenge. Excellent composition and POV.</td>', 'Very interesting approach to the challenge. Excellent composition and POV.', '2004-02-07 08:45:38.000000', NULL, 1),
(571751, 58133, 15305, '<td valign="top">Nice composition, the light from the window creates a very interesting mood.</td>', 'Nice composition, the light from the window creates a very interesting mood.', '2004-02-07 08:48:10.000000', NULL, 1),
(571752, 58512, 15305, '<td valign="top">Interesting composition, remind me of a chess set.</td>', 'Interesting composition, remind me of a chess set.', '2004-02-07 08:48:52.000000', NULL, 1),
(571753, 58242, 15305, '<td valign="top">I''d like to drop by your garage sale... Nice composition and POV</td>', 'I''d like to drop by your garage sale... Nice composition and POV', '2004-02-07 08:49:32.000000', NULL, 1),
