(573593, 57624, 16957, '<td valign="top">Like it - art in the garage.</td>', 'Like it - art in the garage.', '2004-02-09 16:03:58.000000', NULL, 1),
(573595, 58406, 16957, '<td valign="top">Lovely. Excellent lighting and an imaginative still life. Well done.</td>', 'Lovely. Excellent lighting and an imaginative still life. Well done.', '2004-02-09 16:05:10.000000', NULL, 1),
(573596, 58531, 16957, '<td valign="top">Nicely done. I like the fact that all the screws are slightly different.</td>', 'Nicely done. I like the fact that all the screws are slightly different.', '2004-02-09 16:06:06.000000', NULL, 1),
(573601, 57933, 16957, '<td valign="top">Fantastic. How long did it take to get all these nails in place? Beautiful symmetry. A 10 for this one.</td>', 'Fantastic. How long did it take to get all these nails in place? Beautiful symmetry. A 10 for this one.', '2004-02-09 16:08:33.000000', NULL, 1),
(573605, 58474, 16957, '<td valign="top">Like it. Good grey tones.</td>', 'Like it. Good grey tones.', '2004-02-09 16:10:15.000000', NULL, 1),
(573610, 57924, 16957, '<td valign="top">Nice idea. Not sure it worlks too well on this background. Wood grain ik find a bit distracting. also might - just might- have been an idea to use at least one other medium - drips or lines of oil perhaps?</td>', 'Nice idea. Not sure it worlks too well on this background. Wood grain ik find a bit distracting. also might - just might- have been an idea to use at least one other medium - drips or lines of oil perhaps?', '2004-02-09 16:12:07.000000', NULL, 1),
(573613, 58359, 16957, '<td valign="top">Mm!! Good shot but garage art?</td>', 'Mm!! Good shot but garage art?', '2004-02-09 16:13:42.000000', NULL, 1),
(573614, 57675, 16957, '<td valign="top">Lovely composition and colours.</td>', 'Lovely composition and colours.', '2004-02-09 16:14:29.000000', NULL, 1),
(573617, 57370, 1344, '<td valign="top">ribbon...9</td>', 'ribbon...9', '2004-02-09 16:15:04.000000', NULL, 1),
(573620, 58416, 16957, '<td valign="top">Wonderful - a top five - maybe a winner?</td>', 'Wonderful - a top five - maybe a winner?', '2004-02-09 16:15:33.000000', NULL, 1),
(573622, 57937, 16957, '<td valign="top">imaginative - scores for this alone.</td>', 'imaginative - scores for this alone.', '2004-02-09 16:16:26.000000', NULL, 1),
(573630, 58113, 16957, '<td valign="top">Lots of nuts and bolts in this challenge so need to excel to make a mark. This image might have but lacks a focal point. Wahsed out faces of nuts seem to contradict the one feature that makes this a good topic for photopgraphy - the fine machining.</td>', 'Lots of nuts and bolts in this challenge so need to excel to make a mark. This image might have but lacks a focal point. Wahsed out faces of nuts seem to contradict the one feature that makes this a good topic for photopgraphy - the fine machining.', '2004-02-09 16:18:23.000000', NULL, 1),
(573632, 58515, 16957, '<td valign="top">Let''s see more of the blade given the title?</td>', 'Let''s see more of the blade given the title?', '2004-02-09 16:19:20.000000', NULL, 1),
(573634, 57398, 16957, '<td valign="top">Nice idea. Not sure it works but well done for thinking laterally.</td>', 'Nice idea. Not sure it works but well done for thinking laterally.', '2004-02-09 16:20:23.000000', NULL, 1);
