(574622, 58310, 17151, '<td valign="top">Has the milk turned green? ;o)</td>', 'Has the milk turned green? ;o)', '2004-02-10 13:55:13.000000', NULL, 1),
(574630, 58333, 16672, '<td valign="top">The set up is there sure but what does it mean why should we the audience care to stare at a set up on a single image which seems very contribed for what reason its not clear. The lighting is a be harsh on the right side though and bluish. You may also think about your cropping again its a bit tight on the hammer head. I do love that its crisp and sharp well just keep working away kudos to you for now!</td>', 'The set up is there sure but what does it mean why should we the audience care to stare at a set up on a single image which seems very contribed for what reason its not clear. The lighting is a be harsh on the right side though and bluish. You may also think about your cropping again its a bit tight on the hammer head. I do love that its crisp and sharp well just keep working away kudos to you for now!', '2004-02-10 13:58:31.000000', NULL, 1),
(574634, 57964, 16672, '<td valign="top">Don''t know its a clear view but beyond that nothing and how it fits in I guess you found it in a pile of rubish or a box but you removed it from its home.</td>', 'Don''t know its a clear view but beyond that nothing and how it fits in I guess you found it in a pile of rubish or a box but you removed it from its home.', '2004-02-10 14:00:39.000000', NULL, 1),
(574643, 57874, 16672, '<td valign="top">A sincere beauty made by the hearts desire to see!</td>', 'A sincere beauty made by the hearts desire to see!', '2004-02-10 14:06:41.000000', NULL, 1),
