(574689, 57715, 16957, '<td valign="top">Imaginative but maybe apples don''t live in garages?:)</td>', 'Imaginative but maybe apples don''t live in garages?:)', '2004-02-10 15:05:44.000000', NULL, 1),
(574691, 58316, 16957, '<td valign="top">mm - getting to see too many spanners ijn this challenge but....vote on all equally. Like the choice of colours here. Might be improved with slightly better focus? Fine shot though.</td>', 'mm - getting to see too many spanners ijn this challenge but....vote on all equally. Like the choice of colours here. Might be improved with slightly better focus? Fine shot though.', '2004-02-10 15:07:53.000000', NULL, 1),
(574692, 58457, 11467, '<td valign="top">Ooh, I''ve worked out now... thats a supermarket wagon ;-)<br/>Maybe should have made more of a robot form. The first few times I looked at this I thought it was just a pile of junk stacked in a corner.</td>', 'Ooh, I''ve worked out now... thats a supermarket wagon ;-)Maybe should have made more of a robot form. The first few times I looked at this I thought it was just a pile of junk stacked in a corner.', '2004-02-10 15:08:28.000000', NULL, 1),
(574693, 58216, 16957, '<td valign="top">Nice idea. Not sure I like the bubblewrap. Also green oil(?) is opaque others aren''t. Would score higher if there was more consitency. Remain a bit undecided about this one!</td>', 'Nice idea. Not sure I like the bubblewrap. Also green oil(?) is opaque others aren''t. Would score higher if there was more consitency. Remain a bit undecided about this one!', '2004-02-10 15:10:12.000000', NULL, 1),
(574694, 58392, 16957, '<td valign="top">Like this. Well captured.</td>', 'Like this. Well captured.', '2004-02-10 15:11:19.000000', NULL, 1),
(574695, 58484, 16957, '<td valign="top">Personally there''s too many things here competing for my attention. The car, the opening, the fish stencil. Pinning this shot down to fewer elements would grab my attention more but nice shot nevertheless.</td>', 'Personally there''s too many things here competing for my attention. The car, the opening, the fish stencil. Pinning this shot down to fewer elements would grab my attention more but nice shot nevertheless.', '2004-02-10 15:13:10.000000', NULL, 1),
(574697, 58333, 16957, '<td valign="top">Imaginative - score on this alone. Am trying to think whether composing this in the conventional way (as a diner would see it sitting at a table) woudl improvide it. On reflection I like the alternative interpretation..!</td>', 'Imaginative - score on this alone. Am trying to think whether composing this in the conventional way (as a diner would see it sitting at a table) woudl improvide it. On reflection I like the alternative interpretation..!', '2004-02-10 15:14:59.000000', NULL, 1),
(574698, 58490, 16957, '<td valign="top">You keep a nice chessboard like this in your garage?! Like the mood but scores less cos of dodgy garage connection :)</td>', 'You keep a nice chessboard like this in your garage?! Like the mood but scores less cos of dodgy garage connection :)', '2004-02-10 15:16:00.000000', NULL, 1),
(574700, 57459, 16957, '<td valign="top">Nice study though found metallic background distracts attention from the metallic texture of spanner.</td>', 'Nice study though found metallic background distracts attention from the metallic texture of spanner.', '2004-02-10 15:17:22.000000', NULL, 1),
(574701, 58306, 16957, '<td valign="top">Simple but very effective. love the colour details.</td>', 'Simple but very effective. love the colour details.', '2004-02-10 15:18:27.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(574703, 58520, 16957, '<td valign="top">Nice composition and excellent lighting.</td>', 'Nice composition and excellent lighting.', '2004-02-10 15:19:09.000000', NULL, 1),
(574704, 58420, 16957, '<td valign="top">Lovely use of b&amp;w and beautiful reflections and textures.</td>', 'Lovely use of b&w and beautiful reflections and textures.', '2004-02-10 15:21:17.000000', NULL, 1),
(574706, 58494, 16695, '<td valign="top">Welp, the bikes are certainly off road, no denying that.But the shot feels cluttered and a little hard to follow.  Perhaps removing those tolls in the back wold have helping clean up the background.</td>', 'Welp, the bikes are certainly off road, no denying that.But the shot feels cluttered and a little hard to follow.  Perhaps removing those tolls in the back wold have helping clean up the background.', '2004-02-10 15:22:26.000000', NULL, 1),
(574708, 58023, 16957, '<td valign="top">This shot needs to be much better focussed and am unsure that the harsh transition from tool board to clock does the picture any favours. Keep at it!</td>', 'This shot needs to be much better focussed and am unsure that the harsh transition from tool board to clock does the picture any favours. Keep at it!', '2004-02-10 15:24:03.000000', NULL, 1),
(574709, 57487, 16957, '<td valign="top">garage art..... garage art..... garage art.......mmmmmm</td>', 'garage art..... garage art..... garage art.......mmmmmm', '2004-02-10 15:25:42.000000', NULL, 1),
(574717, 57370, 4090, '<td valign="top">stunning - a ribbon tomorrow I hope - good luck</td>', 'stunning - a ribbon tomorrow I hope - good luck', '2004-02-10 15:36:09.000000', NULL, 1),
(574721, 58519, 16695, '<td valign="top">Cool idea and fun execution, but the composition seems to be lacking.  Very static, straight on angle; rough background.  Still a cool shot, but I think it could be worked on.</td>', 'Cool idea and fun execution, but the composition seems to be lacking.  Very static, straight on angle; rough background.  Still a cool shot, but I think it could be worked on.', '2004-02-10 15:42:50.000000', NULL, 1),
(574723, 57532, 16497, '<td valign="top">Nice composition and a cool concept!</td>', 'Nice composition and a cool concept!', '2004-02-10 15:44:36.000000', NULL, 1),
(574728, 57787, 16695, '<td valign="top">nice, simple composition... but the foreground seems to lack any sort of contrast or something that would otherwise distinguish it.</td>', 'nice, simple composition... but the foreground seems to lack any sort of contrast or something that would otherwise distinguish it.', '2004-02-10 15:47:39.000000', NULL, 1),
(574735, 58242, 16695, '<td valign="top">;) clever</td>', ';) clever', '2004-02-10 15:57:15.000000', NULL, 1),
(574748, 57715, 16497, '<td valign="top">great concept!  i find the shadow distracting though...</td>', 'great concept!  i find the shadow distracting though...', '2004-02-10 16:18:04.000000', NULL, 1),
(574750, 58533, 16497, '<td valign="top">i like the composition, no detail in he leather though!</td>', 'i like the composition, no detail in he leather though!', '2004-02-10 16:19:54.000000', NULL, 1),
(574768, 58531, 16497, '<td valign="top">nicely done!  i''m all for simplicity and straightforward ideas.  what''s strange about the reflections?</td>', 'nicely done!  i''m all for simplicity and straightforward ideas.  what''s strange about the reflections?', '2004-02-10 16:38:22.000000', NULL, 1),
(574769, 58359, 12160, '<td valign="top">nice detail and focus, good shallow dof</td>', 'nice detail and focus, good shallow dof', '2004-02-10 16:39:21.000000', NULL, 1),
(574772, 57370, 16497, '<td valign="top">i see a career in commercial photography in your future!  a little trouble with skin tones though.</td>', 'i see a career in commercial photography in your future!  a little trouble with skin tones though.', '2004-02-10 16:39:49.000000', NULL, 1),
(574775, 57726, 16497, '<td valign="top">i''m not sure what to make of it, but i kinda like it!</td>', 'i''m not sure what to make of it, but i kinda like it!', '2004-02-10 16:42:28.000000', NULL, 1),
(574776, 57504, 12160, '<td valign="top">i like the curve and the circles. very nice b/w photo. 9</td>', 'i like the curve and the circles. very nice b/w photo. 9', '2004-02-10 16:43:16.000000', NULL, 1),
(574779, 57627, 12160, '<td valign="top">i like the mood of this photo. well-composed, simple and powerful. 8 - bumping to 9</td>', 'i like the mood of this photo. well-composed, simple and powerful. 8 - bumping to 9', '2004-02-10 16:43:58.000000', NULL, 1),
(574780, 58398, 16497, '<td valign="top">well done, i''m not sure about the cast though!</td>', 'well done, i''m not sure about the cast though!', '2004-02-10 16:44:13.000000', NULL, 1),
(574782, 58502, 12160, '<td valign="top">artistic, good composition, nice textures. have to go back and think about the color saturation. will start at 7 - bumping to 8</td>', 'artistic, good composition, nice textures. have to go back and think about the color saturation. will start at 7 - bumping to 8', '2004-02-10 16:44:54.000000', NULL, 1),
(574783, 57715, 12160, '<td valign="top">No clue what the title is saying but the photo is beautiful.</td>', 'No clue what the title is saying but the photo is beautiful.', '2004-02-10 16:45:08.000000', NULL, 1),
(574786, 58044, 16497, '<td valign="top">nice compostion!  oversharpened?</td>', 'nice compostion!  oversharpened?', '2004-02-10 16:49:49.000000', NULL, 1),
(574832, 57627, 2158, '<td valign="top">Nice, but I''m not sure it fits the challenge.</td>', 'Nice, but I''m not sure it fits the challenge.', '2004-02-10 17:40:34.000000', NULL, 1),
(574859, 58333, 2158, '<td valign="top">Nice and creative fun shot.</td>', 'Nice and creative fun shot.', '2004-02-10 17:56:52.000000', NULL, 1),
(574867, 58044, 7628, '<td valign="top">I like the blue light and the texture in your subject.  Wish all of the cord were included.  Lighting is a bit flat, seems a bit dark.</td>', 'I like the blue light and the texture in your subject.  Wish all of the cord were included.  Lighting is a bit flat, seems a bit dark.', '2004-02-10 18:08:03.000000', NULL, 1),
(574869, 57609, 7628, '<td valign="top">You got some nice detail in the texture of the dried paint.  I like the drop cloths too.  The colors work well together.  I wish there were more of an angle here - seeing into the can more, or having more of a diagonal composition.</td>', 'You got some nice detail in the texture of the dried paint.  I like the drop cloths too.  The colors work well together.  I wish there were more of an angle here - seeing into the can more, or having more of a diagonal composition.', '2004-02-10 18:10:40.000000', NULL, 1),
(574874, 58501, 7628, '<td valign="top">good idea for a subject.  I like all that red.  The light is a bit glaring, especially off the garage door.  A couple of lights pointing from different sides would create more interesting shapes and textures.</td>', 'good idea for a subject.  I like all that red.  The light is a bit glaring, especially off the garage door.  A couple of lights pointing from different sides would create more interesting shapes and textures.', '2004-02-10 18:12:31.000000', NULL, 1),
(574876, 58523, 7628, '<td valign="top">"Cool!" is the first thought that popped into my head as this came up on the screen.  Lovely composition, lighting.  Nice metslic textures, super spinning effect.Good idea, well done!  10</td>', '"Cool!" is the first thought that popped into my head as this came up on the screen.  Lovely composition, lighting.  Nice metslic textures, super spinning effect.Good idea, well done!  10', '2004-02-10 18:14:15.000000', NULL, 1),
(574878, 58335, 7628, '<td valign="top">I like the simplicity and dof.  The colors are interesting too.  Perfectly vertical or more of a diagonal might be a bit better. 7</td>', 'I like the simplicity and dof.  The colors are interesting too.  Perfectly vertical or more of a diagonal might be a bit better. 7', '2004-02-10 18:16:10.000000', NULL, 1),
(574884, 58472, 7628, '<td valign="top">I like the colors and textures here - works well with the challenge.  Good subject.  I like the composition too - small sections of curves and spokes fill the frame pleasingly.8</td>', 'I like the colors and textures here - works well with the challenge.  Good subject.  I like the composition too - small sections of curves and spokes fill the frame pleasingly.8', '2004-02-10 18:19:33.000000', NULL, 1),
(574886, 57703, 7628, '<td valign="top">I like the lighting here - lovely enough for a more graceful subject, still, this works with the challenge.</td>', 'I like the lighting here - lovely enough for a more graceful subject, still, this works with the challenge.', '2004-02-10 18:20:48.000000', NULL, 1),
(574892, 57871, 7628, '<td valign="top">funny - that is some parking job!  Nice touch with the tire tracks in the snow.  There is a distracting tilt to this, and the light is a bit glaring.  Might have been cooler at night when the inside of the garage would be dark, and you could selectively light the car and the tracks.</td>', 'funny - that is some parking job!  Nice touch with the tire tracks in the snow.  There is a distracting tilt to this, and the light is a bit glaring.  Might have been cooler at night when the inside of the garage would be dark, and you could selectively light the car and the tracks.', '2004-02-10 18:23:00.000000', NULL, 1),
(574897, 58193, 7628, '<td valign="top">I like the juxtiposition of the car and the plant with the structure and shadows framing them.  Nice tones and textures.  I do wish the whole car werre included. 8</td>', 'I like the juxtiposition of the car and the plant with the structure and shadows framing them.  Nice tones and textures.  I do wish the whole car werre included. 8', '2004-02-10 18:32:29.000000', NULL, 1),
(574900, 58373, 7628, '<td valign="top">I like your concept and the colors.  The lighting really hightlights the texture of the paint o the bristles.  I wish there were splashes of paint in the background, it distracts and detracts from the nice composition.  I''d almost want to crop it down just tp the bristles</td>', 'I like your concept and the colors.  The lighting really hightlights the texture of the paint o the bristles.  I wish there were splashes of paint in the background, it distracts and detracts from the nice composition.  I''d almost want to crop it down just tp the bristles', '2004-02-10 18:35:04.000000', NULL, 1),
(574902, 58520, 2158, '<td valign="top">I love the idea, but perhaps a bit more light on the handle??</td>', 'I love the idea, but perhaps a bit more light on the handle??', '2004-02-10 18:40:59.000000', NULL, 1),
(574921, 58513, 14155, '<td valign="top">Good light. The colors are vivid. Good photo.</td>', 'Good light. The colors are vivid. Good photo.', '2004-02-10 19:18:56.000000', NULL, 1),
(574926, 57370, 6624, '<td valign="top">wonderful energy in this</td>', 'wonderful energy in this', '2004-02-10 19:26:31.000000', NULL, 1),
(574927, 57798, 6624, '<td valign="top">nice light, colors, textures</td>', 'nice light, colors, textures', '2004-02-10 19:27:20.000000', NULL, 1),
(574938, 58456, 8125, '<td valign="top">Looks like your white balance is off a little - your background is pinkish rather than white.  I''m not a big fan of the dark shadow, a little less might have been better.</td>', 'Looks like your white balance is off a little - your background is pinkish rather than white.  I''m not a big fan of the dark shadow, a little less might have been better.', '2004-02-10 19:43:58.000000', NULL, 1),
(574940, 57674, 8125, '<td valign="top">The image size is a bit small to really see the details.  Looks like you might have some overexposure as the white parts of this shot appear to be blown out.</td>', 'The image size is a bit small to really see the details.  Looks like you might have some overexposure as the white parts of this shot appear to be blown out.', '2004-02-10 19:45:17.000000', NULL, 1),
(574941, 57608, 8125, '<td valign="top">There appears to be some noise in this shot.</td>', 'There appears to be some noise in this shot.', '2004-02-10 19:45:36.000000', NULL, 1),
(574943, 57797, 8125, '<td valign="top">The rims don''t match on this?</td>', 'The rims don''t match on this?', '2004-02-10 19:46:11.000000', NULL, 1),
(574946, 58542, 8125, '<td valign="top">Excellent use of black and white/sepia tone.  The grain in this shot works really well also.  I''d like to see the same thing without the toilet and cardboard, but it''s still a great shot.</td>', 'Excellent use of black and white/sepia tone.  The grain in this shot works really well also.  I''d like to see the same thing without the toilet and cardboard, but it''s still a great shot.', '2004-02-10 19:47:32.000000', NULL, 1),
(574950, 58512, 8125, '<td valign="top">I think this could use some sharpening maybe. it seems a little soft to me.</td>', 'I think this could use some sharpening maybe. it seems a little soft to me.', '2004-02-10 19:48:07.000000', NULL, 1),
(574955, 57911, 8125, '<td valign="top">This looks like my husband''s decorating  :-)   I love the use of black and white.  Good lighting, good composition, overall a great shot.</td>', 'This looks like my husband''s decorating  :-)   I love the use of black and white.  Good lighting, good composition, overall a great shot.', '2004-02-10 19:49:21.000000', NULL, 1),
(574956, 58238, 8125, '<td valign="top">This would look better on a solid background without the bright flash spot.</td>', 'This would look better on a solid background without the bright flash spot.', '2004-02-10 19:49:57.000000', NULL, 1),
(574958, 58520, 8125, '<td valign="top">Good idea, well executed.  I like the lighting and composition.  I wonder what this would like in black and white as well?  Good job!  :-)</td>', 'Good idea, well executed.  I like the lighting and composition.  I wonder what this would like in black and white as well?  Good job!  :-)', '2004-02-10 19:51:24.000000', NULL, 1),
(574961, 58038, 8125, '<td valign="top">Since there are already bent nails in this composition, it might be better to leave the extras out.  It does still look good the way you have it.  The lighting seems a little uneven as you have a brighter area in the upper right hand side, but that might have been intentional.  Overall, a good idea and well executed.</td>', 'Since there are already bent nails in this composition, it might be better to leave the extras out.  It does still look good the way you have it.  The lighting seems a little uneven as you have a brighter area in the upper right hand side, but that might have been intentional.  Overall, a good idea and well executed.', '2004-02-10 19:53:16.000000', NULL, 1),
(574966, 57627, 8125, '<td valign="top">I don''t really care for the border, but I like the color tone and grain.  Lighting looks good also.</td>', 'I don''t really care for the border, but I like the color tone and grain.  Lighting looks good also.', '2004-02-10 19:54:02.000000', NULL, 1),
(574967, 57433, 8125, '<td valign="top">The focus seems soft here.</td>', 'The focus seems soft here.', '2004-02-10 19:54:17.000000', NULL, 1),
(574969, 58523, 8125, '<td valign="top">Wow... cool shot.  :-)  Love the black and white, lighting and composition are good.  Nice work....</td>', 'Wow... cool shot.  :-)  Love the black and white, lighting and composition are good.  Nice work....', '2004-02-10 19:55:03.000000', NULL, 1),
(574970, 58461, 8125, '<td valign="top">Looks a little soft on focus.</td>', 'Looks a little soft on focus.', '2004-02-10 19:55:22.000000', NULL, 1),
(574971, 58506, 8125, '<td valign="top">Love the use of black and white as well as the grain.  The right side is getting pretty dark so it loses some detail.</td>', 'Love the use of black and white as well as the grain.  The right side is getting pretty dark so it loses some detail.', '2004-02-10 19:56:07.000000', NULL, 1),
(574975, 58238, 6668, '<td valign="top">Nice idea, would have worked better with a solid background in my opinion.</td>', 'Nice idea, would have worked better with a solid background in my opinion.', '2004-02-10 19:58:01.000000', NULL, 1),
(574979, 58292, 8125, '<td valign="top">I''m sorry - I just don''t see this fitting well in Garage Art.  I think I understand where you were going with it, but it just doesn''t work for me.  Outside of that - your lighting is good.  The dof is too shallow.</td>', 'I''m sorry - I just don''t see this fitting well in Garage Art.  I think I understand where you were going with it, but it just doesn''t work for me.  Outside of that - your lighting is good.  The dof is too shallow.', '2004-02-10 20:01:42.000000', NULL, 1),
